2	package org.springframework.samples.petclinic.rest.function.owner;
3	
4	import net.officefloor.plugin.variable.Out;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.web.bind.annotation.RequestBody;
7	
8	/**
9	 * Normalizes a create-owner request's address to its canonical form (see {@link AddressNormalizer}:
10	 * trim, collapse whitespace, upper-case, expand common abbreviations) before any other step runs. Binds
11	 * the request body (the single {@code @RequestBody} step of this pipeline) and republishes it as a
12	 * variable for the later steps.
13	 *
14	 * <p>The address may arrive in either form. The structured fields are preferred when present: a
15	 * non-blank {@code addressLine1} (with an optional {@code addressLine2}) is normalized line-by-line and
16	 * composed into the flat {@code address} — the normalized {@code addressLine1}, with a single space and
17	 * the normalized {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the
18	 * flat {@code address} input is normalized as before, keeping the create contract backward-compatible.
19	 * Either way the normalized {@code address} is what {@link RequireOwnerFields} tests for blankness, what
20	 * everything reading the address derives from, and what {@link BuildOwner} maps to the entity — so it is
21	 * stored and returned, alongside the normalized structured fields.
22	 */
23	public class NormalizeAddress {
24	
25	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> normalized) {
26	        String line1 = request.getAddressLine1();
27	        if (line1 != null && !line1.isBlank()) {
28	            String normalizedLine1 = AddressNormalizer.normalize(line1);
29	            String normalizedLine2 = AddressNormalizer.normalize(request.getAddressLine2());
30	            request.setAddressLine1(normalizedLine1);
31	            request.setAddressLine2(normalizedLine2.isEmpty() ? null : normalizedLine2);
32	            request.setAddress(normalizedLine2.isEmpty() ? normalizedLine1
33	                    : normalizedLine1 + " " + normalizedLine2);
34	        }
35	        else {
36	            request.setAddress(AddressNormalizer.normalize(request.getAddress()));
37	        }
38	        normalized.set(request);
39	    }
40	}
