43	package org.springframework.samples.petclinic.rest.function.owner;
44	
45	import java.util.ArrayList;
46	import java.util.List;
47	
48	import net.officefloor.plugin.variable.Val;
49	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
50	
51	/**
52	 * Rejects a create-owner request that is missing or blank in any mandatory field, before the body is
53	 * mapped to an entity. Reads the request published by {@link NormalizeAddress}, so the address has
54	 * already been normalized and composed. An owner is valid when it supplies an address in either form —
55	 * a non-blank {@code addressLine1} or the flat {@code address} — so a request blank in both (including
56	 * blank-after-normalization) is rejected here.
57	 */
58	public class RequireOwnerFields {
59	
60	    public void service(@Val OwnerFieldsDto request) throws MissingOwnerFieldsException {
61	        List<String> missing = new ArrayList<>();
62	        if (isBlank(request.getFirstName())) {
63	            missing.add("firstName");
64	        }
65	        if (isBlank(request.getLastName())) {
66	            missing.add("lastName");
67	        }
68	        if (isBlank(request.getAddressLine1()) && isBlank(request.getAddress())) {
69	            missing.add("address");
70	        }
71	        if (isBlank(request.getCity())) {
72	            missing.add("city");
73	        }
74	        if (isBlank(request.getTelephone())) {
75	            missing.add("telephone");
76	        }
77	        if (!missing.isEmpty()) {
78	            throw new MissingOwnerFieldsException(missing);
79	        }
80	    }
81	
82	    private static boolean isBlank(String value) {
83	        return value == null || value.isBlank();
84	    }
85	}
