94	
95	/**
96	 * Rejects a create-owner request whose supplied {@code registrationDate} is later than the current
97	 * server date. The date is optional: when absent the request is accepted unchanged (and
98	 * {@link BuildOwner} defaults it to the server date). A future date is rejected via
99	 * {@link FutureRegistrationDateException}, which the global handler turns into a 400. Runs before the
100	 * owner is built and saved.
101	 */
102	public class RejectFutureRegistrationDate {
103	
104	    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
105	        LocalDate supplied = request.getRegistrationDate();
106	        if (supplied == null) {
107	            return; // registrationDate is optional; nothing to validate when absent
108	        }
109	        LocalDate today = LocalDate.now();
110	        if (supplied.isAfter(today)) {
111	            throw new FutureRegistrationDateException(supplied, today);
112	        }
113	    }
114	}
