116	==================== ValidatePostcode.java ====================
117	package org.springframework.samples.petclinic.rest.function.owner;
118	
119	import net.officefloor.plugin.variable.Val;
120	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
121	
122	/**
123	 * Validates an owner request's optional {@code postcode}. When absent (null or blank) the request is
124	 * accepted unchanged, keeping the create contract backward-compatible. When present the postcode must be
125	 * exactly four digits and, for a city whose region is known (via {@link Locality}), must fall within that
126	 * region's range (see {@link PostcodeRanges}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
127	 * known region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected via
128	 * {@link InvalidPostcodeException}, which the global handler turns into a 400.
129	 */
130	public class ValidatePostcode {
131	
132	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
133	        String postcode = request.getPostcode();
134	        if (postcode == null || postcode.isBlank()) {
135	            return; // postcode is optional; nothing to validate when absent
136	        }
137	        if (!postcode.matches("[0-9]{4}")) {
138	            throw InvalidPostcodeException.malformed(postcode);
139	        }
140	        String region = Locality.of(request.getCity());
141	        int[] range = PostcodeRanges.forRegion(region);
142	        if (range == null) {
143	            return; // no known region for this city -> any 4-digit postcode is accepted
144	        }
145	        int value = Integer.parseInt(postcode);
146	        if (value < range[0] || value > range[1]) {
147	            throw InvalidPostcodeException.outOfRange(postcode, request.getCity(), region, range);
148	        }
149	    }
150	}
