153	package org.springframework.samples.petclinic.rest.function.owner;
154	
155	import net.officefloor.plugin.variable.Val;
156	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
157	
158	/**
159	 * Normalizes a create-owner request's telephone to E.164 form: a leading {@code '+'} and country code
160	 * are kept when present, otherwise country code {@code '+61'} is assumed and a single leading
161	 * {@code '0'} is dropped from the national digits; spaces, dashes and brackets are stripped and 8 to 15
162	 * digits are required after the {@code '+'}. So {@code '0412 345 678'} becomes {@code '+61412345678'}.
163	 * The normalized value is written back onto the request (the same object the later {@link BuildOwner}
164	 * step maps to the entity), so it is stored and returned as {@code telephone}. A number that cannot
165	 * form valid E.164 is rejected via {@link InvalidTelephoneException}, which the global handler turns
166	 * into a 400.
167	 */
168	public class NormalizeTelephone {
169	
170	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
171	        request.setTelephone(TelephoneE164.normalize(request.getTelephone()));
172	    }
173	}
