175	==================== NormalizeEmail.java ====================
176	package org.springframework.samples.petclinic.rest.function.owner;
177	
178	import java.util.Locale;
179	import java.util.regex.Pattern;
180	
181	import net.officefloor.plugin.variable.Val;
182	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
183	
184	/**
185	 * Normalizes an owner request's optional {@code email}. Email is optional, so an absent or blank
186	 * value is left untouched. When present it must be a syntactically valid address; otherwise the
187	 * request is rejected via {@link InvalidEmailException}, which the global handler turns into a 400.
188	 * A valid value is lower-cased and written back onto the request (the same object the later
189	 * {@link BuildOwner}/{@link ApplyOwner} step maps to the entity), so it is stored and returned
190	 * lower-cased as {@code email}.
191	 */
192	public class NormalizeEmail {
193	
194	    /** A basic syntactic check: non-empty local part, '@', domain with at least one dot. */
195	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
196	
197	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
198	        String raw = request.getEmail();
199	        if (raw == null || raw.isBlank()) {
200	            return;
201	        }
202	        String email = raw.trim();
203	        if (!EMAIL.matcher(email).matches()) {
204	            throw new InvalidEmailException(raw);
205	        }
206	        request.setEmail(email.toLowerCase(Locale.ROOT));
207	    }
208	}
