211	package org.springframework.samples.petclinic.rest.function.owner;
212	
213	import java.util.Locale;
214	import java.util.Set;
215	
216	import net.officefloor.plugin.variable.Val;
217	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
218	
219	/**
220	 * Rejects a create-owner request whose {@code email} domain is on the disposable-domain blocklist.
221	 * Email is optional, so an absent or blank value is left untouched. Runs after {@link NormalizeEmail}
222	 * has validated the syntax and lower-cased the value, so the domain is matched case-insensitively.
223	 * A blocked domain is rejected via {@link DisposableEmailDomainException}, which the global handler
224	 * turns into a 400.
225	 */
226	public class RejectDisposableEmailDomain {
227	
228	    /** Domains whose addresses are rejected. */
229	    static final Set<String> BLOCKED_DOMAINS = Set.of(
230	            "mailinator.com", "tempmail.com", "guerrillamail.com");
231	
232	    public void service(@Val OwnerFieldsDto request) throws DisposableEmailDomainException {
233	        String raw = request.getEmail();
234	        if (raw == null || raw.isBlank()) {
235	            return;
236	        }
237	        int at = raw.lastIndexOf('@');
238	        if (at < 0) {
239	            return;
240	        }
241	        String domain = raw.substring(at + 1).trim().toLowerCase(Locale.ROOT);
242	        if (BLOCKED_DOMAINS.contains(domain)) {
243	            throw new DisposableEmailDomainException(domain);
244	        }
245	    }
246	}
