248	==================== RejectDuplicateOwner.java ====================
249	package org.springframework.samples.petclinic.rest.function.owner;
250	
251	import net.officefloor.plugin.variable.Val;
252	import org.springframework.samples.petclinic.model.Owner;
253	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
254	import org.springframework.samples.petclinic.repository.OwnerRepository;
255	
256	/**
257	 * Household duplicate detection for create-owner — "the duplicate block". Duplicate detection keys off
258	 * the household, which is now the deterministic {@link HouseholdId} derived from the last name and
259	 * postcode: two owners belong to the same household exactly when they share a {@code householdId}.
260	 * Because the household is keyed on {@code (lastName, postcode)}, a second owner matching an existing
261	 * owner's last name and postcode is a household duplicate and is rejected via
262	 * {@link DuplicateIdentityException}, which the global handler turns into a 409.
263	 *
264	 * <p>A request that sets {@code sharesHousehold} true bypasses this block: it is a declared household
265	 * member and is created (see {@link DetectPossibleDuplicate}, which does not flag a declared member as a
266	 * suspected duplicate). {@code sharesHousehold} now only bypasses the duplicate block; the shared
267	 * {@code householdId} is derived automatically, not linked. Runs before the owner is built and saved,
268	 * so {@link OwnerRepository#findAll()} sees only the owners that existed before this create.
269	 */
270	public class RejectDuplicateOwner {
271	
272	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
273	            throws DuplicateIdentityException {
274	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
275	            return; // declared household member — bypass the duplicate block
276	        }
277	        String householdId = HouseholdId.of(request.getLastName(), request.getPostcode());
278	        for (Owner existing : ownerRepository.findAll()) {
279	            if (Boolean.TRUE.equals(existing.getDeleted())) {
280	                continue; // soft-deleted owners are ignored by the duplicate check
281	            }
282	            if (householdId.equals(HouseholdId.of(existing.getLastName(), existing.getPostcode()))) {
283	                throw new DuplicateIdentityException(IdentityKey.of(request.getTelephone(),
284	                        request.getEmail(), request.getLastName(), request.getPostcode()));
285	            }
286	        }
287	    }
288	}
