290	==================== RejectCityAtCapacity.java ====================
291	package org.springframework.samples.petclinic.rest.function.owner;
292	
293	import java.util.Locale;
294	
295	import net.officefloor.plugin.variable.Val;
296	import org.springframework.samples.petclinic.model.Owner;
297	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
298	import org.springframework.samples.petclinic.repository.OwnerRepository;
299	
300	/**
301	 * Rejects a create-owner request whose city already contains {@link #CITY_CAPACITY} or more owners.
302	 * Runs before the owner is built and saved. Cities are matched case-insensitively after trimming and
303	 * collapsing runs of whitespace to a single space. A city at capacity is rejected via
304	 * {@link CityAtCapacityException}, which the global handler turns into a 409.
305	 */
306	public class RejectCityAtCapacity {
307	
308	    /** Maximum number of owners allowed per city; the request is rejected once this many already exist. */
309	    static final int CITY_CAPACITY = 50;
310	
311	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
312	            throws CityAtCapacityException {
313	        String city = normalize(request.getCity());
314	        int count = 0;
315	        for (Owner existing : ownerRepository.findAll()) {
316	            if (city.equals(normalize(existing.getCity()))) {
317	                count++;
318	            }
319	        }
320	        if (count >= CITY_CAPACITY) {
321	            throw new CityAtCapacityException(request.getCity(), CITY_CAPACITY);
322	        }
323	    }
324	
325	    private static String normalize(String value) {
326	        if (value == null) {
327	            return "";
328	        }
329	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
330	    }
331	}
