333	==================== RejectOverDailyLimit.java ====================
334	package org.springframework.samples.petclinic.rest.function.owner;
335	
336	import java.time.LocalDate;
337	
338	import net.officefloor.plugin.variable.Val;
339	import org.springframework.samples.petclinic.model.Owner;
340	import org.springframework.samples.petclinic.repository.OwnerRepository;
341	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
342	
343	/**
344	 * Rejects a create-owner request once {@link #DAILY_LIMIT} or more owners have already been created
345	 * for the request's adjusted business day, counting existing owners whose {@code registrationDate}
346	 * equals that day. The day is the effective registration date (supplied in the request or defaulted
347	 * to the server date) rolled forward off any weekend to the next Monday, matching how
348	 * {@link BuildOwner} stores it. Runs before the owner is built and saved. At capacity the request is
349	 * rejected via {@link DailyLimitExceededException}, which the global handler turns into a 429.
350	 */
351	public class RejectOverDailyLimit {
352	
353	    /** Maximum owners that may be created in a single day; the request is rejected once this many exist. */
354	    static final int DAILY_LIMIT = 100;
355	
356	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
357	            throws DailyLimitExceededException {
358	        LocalDate effective = request.getRegistrationDate() != null ? request.getRegistrationDate() : LocalDate.now();
359	        LocalDate day = BusinessDay.adjust(effective);
360	        int count = 0;
361	        for (Owner existing : ownerRepository.findAll()) {
362	            if (day.equals(existing.getRegistrationDate())) {
363	                count++;
364	            }
365	        }
366	        if (count >= DAILY_LIMIT) {
367	            throw new DailyLimitExceededException(DAILY_LIMIT);
368	        }
369	    }
370	}
