394	package org.springframework.samples.petclinic.rest.function.owner;
395	
396	import java.nio.charset.StandardCharsets;
397	import java.security.MessageDigest;
398	import java.security.NoSuchAlgorithmException;
399	import java.util.HashSet;
400	import java.util.Locale;
401	import java.util.Set;
402	
403	import net.officefloor.plugin.variable.Val;
404	import org.springframework.samples.petclinic.model.Owner;
405	import org.springframework.samples.petclinic.repository.OwnerRepository;
406	
407	/**
408	 * Assigns the {@code customerCode} formatted {@code <REGION>-<HASH8>}, where REGION is the region
409	 * code derived from the owner's postcode (see {@link Locality}, which prefers the postcode's range,
410	 * falling back to the city table and finally {@code "UNKNOWN"}) and HASH8 is the first 8 upper-case
411	 * hex characters of SHA-256 over the normalized telephone concatenated with the last name (e.g.
412	 * {@code NSW-1A2B3C4D}). The telephone has already been normalized to E.164 form by
413	 * {@link NormalizeTelephone} earlier in the pipeline, so the stored value is used directly.
414	 * <p>
415	 * When the computed code collides with an existing owner's {@code customerCode}, {@code -<n>} is
416	 * appended with the smallest {@code n} of 2 or more that makes it unique (e.g. {@code NSW-1A2B3C4D-2}).
417	 * Runs before the owner is saved, so {@link OwnerRepository#findAll()} sees only the owners that
418	 * existed before this create.
419	 */
420	public class AssignCustomerCode {
421	
422	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
423	        String region = Locality.of(owner.getCity(), owner.getPostcode());
424	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
425	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
426	        String hash8 = shaHex8(telephone + lastName);
427	        String base = region + "-" + hash8;
428	
429	        Set<String> existing = new HashSet<>();
430	        for (Owner other : ownerRepository.findAll()) {
431	            if (other.getCustomerCode() != null) {
432	                existing.add(other.getCustomerCode());
433	            }
434	        }
435	
436	        String customerCode = base;
437	        for (int n = 2; existing.contains(customerCode); n++) {
438	            customerCode = base + "-" + n;
439	        }
440	        owner.setCustomerCode(customerCode);
441	    }
442	
443	    /** First 8 upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code s}. */
444	    private static String shaHex8(String s) {
445	        try {
446	            byte[] digest = MessageDigest.getInstance("SHA-256")
447	                    .digest(s.getBytes(StandardCharsets.UTF_8));
448	            StringBuilder hex = new StringBuilder(digest.length * 2);
449	            for (byte b : digest) {
450	                hex.append(String.format("%02x", b));
451	            }
452	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
453	        }
454	        catch (NoSuchAlgorithmException e) {
455	            throw new IllegalStateException("SHA-256 not available", e);
456	        }
457	    }
458	}
