541	==================== AssignMembershipLevel.java ====================
542	package org.springframework.samples.petclinic.rest.function.owner;
543	
544	import java.time.LocalDate;
545	
546	import net.officefloor.plugin.variable.Val;
547	import org.springframework.samples.petclinic.model.Owner;
548	
549	/**
550	 * Assigns the {@code membershipPoints} score and the derived numeric {@code membershipLevel} at
551	 * creation time. Points start at {@code 0} and accrue: {@code 2} when the owner has an email,
552	 * {@code 1} when {@code namesakeCount} is {@code 0}, {@code 2} for a household of {@code 3} or more
553	 * (from {@code householdSize}), and {@code 3} for a tenure of at least one elapsed fiscal year
554	 * (fiscal years, starting 1 July, between the owner's {@code registrationDate} and the current
555	 * server date). Points map to a level as {@code 1} (0-1 points), {@code 2} (2-3), {@code 3} (4-5)
556	 * and {@code 4} (6 or more). Runs after {@link CountNamesakes} and {@link CountHousehold} so both
557	 * counts are already set.
558	 */
559	public class AssignMembershipLevel {
560	
561	    /** Elapsed fiscal years at or above which the owner qualifies for the tenure points. */
562	    private static final int TENURE_THRESHOLD_FISCAL_YEARS = 1;
563	
564	    /** Household size at or above which the household points are awarded. */
565	    private static final int HOUSEHOLD_THRESHOLD = 3;
566	
567	    public void service(@Val Owner owner) {
568	        int points = 0;
569	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
570	            points += 2;
571	        }
572	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
573	            points += 1;
574	        }
575	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= HOUSEHOLD_THRESHOLD) {
576	            points += 2;
577	        }
578	        if (tenureFiscalYears(owner) >= TENURE_THRESHOLD_FISCAL_YEARS) {
579	            points += 3;
580	        }
581	        owner.setMembershipPoints(points);
582	        owner.setMembershipLevel(levelForPoints(points));
583	    }
584	
585	    private static int levelForPoints(int points) {
586	        if (points <= 1) {
587	            return 1;
588	        }
589	        if (points <= 3) {
590	            return 2;
591	        }
592	        if (points <= 5) {
593	            return 3;
594	        }
595	        return 4;
596	    }
597	
598	    private static int tenureFiscalYears(Owner owner) {
599	        LocalDate registrationDate = owner.getRegistrationDate();
600	        if (registrationDate == null) {
601	            return 0;
602	        }
603	        return FiscalYear.elapsed(registrationDate, LocalDate.now());
604	    }
605	}
