640	package org.springframework.samples.petclinic.rest.function.owner;
641	
642	import net.officefloor.plugin.variable.Val;
643	import org.springframework.samples.petclinic.model.Owner;
644	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
645	import org.springframework.samples.petclinic.repository.OwnerRepository;
646	
647	/**
648	 * Soft-match duplicate detection for create-owner. Runs after the household duplicate block
649	 * ({@link RejectDuplicateOwner}), so any owner reaching here that shares an existing owner's household
650	 * (same {@link HouseholdId} over last name and postcode) got here only by setting
651	 * {@code sharesHousehold} — it is a declared household member. A declared member is not a suspected
652	 * duplicate, so it is never flagged: {@code possibleDuplicate} is set false and
653	 * {@code possibleDuplicateOf} null.
654	 *
655	 * <p>Otherwise, if the owner nonetheless shares an existing owner's household id it is flagged:
656	 * {@code possibleDuplicate} true and {@code possibleDuplicateOf} the matching owner's id (the lowest id
657	 * when several match). Runs before the owner is saved, so {@link OwnerRepository#findAll()} sees only
658	 * owners that existed before this create.
659	 */
660	public class DetectPossibleDuplicate {
661	
662	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
663	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
664	            owner.setPossibleDuplicate(false);
665	            owner.setPossibleDuplicateOf(null);
666	            return; // declared household member — not a suspected duplicate
667	        }
668	        String householdId = HouseholdId.of(owner.getLastName(), owner.getPostcode());
669	        Owner match = null;
670	        for (Owner existing : ownerRepository.findAll()) {
671	            if (Boolean.TRUE.equals(existing.getDeleted())) {
672	                continue; // soft-deleted owners are ignored by the duplicate check
673	            }
674	            if (householdId.equals(HouseholdId.of(existing.getLastName(), existing.getPostcode()))) {
675	                if (match == null || existing.getId() < match.getId()) {
676	                    match = existing;
677	                }
678	            }
679	        }
680	        if (match != null) {
681	            owner.setPossibleDuplicate(true);
682	            owner.setPossibleDuplicateOf(match.getId());
683	        } else {
684	            owner.setPossibleDuplicate(false);
685	            owner.setPossibleDuplicateOf(null);
686	        }
687	    }
688	}
