package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

/**
 * Derives an owner's {@code householdId}: a stable identifier shared by every owner with the same
 * last name and postcode (one household). The last name is normalized (trim, collapse runs of
 * whitespace to a single space, lower-case) and joined to the postcode with a {@code '|'} separator
 * before hashing, so owners with the same last name and postcode — including one created with
 * {@code sharesHousehold} true, which by definition matches an existing owner's last name and
 * postcode — derive the identical value. Computed as the first 12 upper-case hex characters of
 * SHA-256 over {@code normalizedLastName + '|' + postcode}, so it is stable across requests and needs
 * no persisted column.
 */
public final class HouseholdId {

    private HouseholdId() {
    }

    public static String of(String lastName, String postcode) {
        String key = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                hex.append(String.format("%02x", b));
            }
            return hex.substring(0, 12).toUpperCase(Locale.ROOT);
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

==================== IdentityKey.java ====================
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

/**
 * Derives an owner's {@code identityKey}: the single value all duplicate detection is now expressed
 * through. It is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the
 * telephone is normalized to E.164 the same way as {@link NormalizeTelephone}/{@link TelephoneE164},
 * the email is trimmed and lower-cased (empty when absent or blank, the same form as
 * {@link NormalizeEmail}), and the household component is {@link HouseholdId} over the last name and
 * postcode. Because the telephone is part of the key, two members of the same household (same
 * {@code householdId}) with different telephones derive different identityKeys.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    public static String of(String telephone, String email, String lastName, String postcode) {
        String normalizedTelephone = TelephoneE164.normalizeOrNull(telephone);
        if (normalizedTelephone == null) {
            normalizedTelephone = telephone == null ? "" : telephone.trim();
        }
        String normalizedEmail = (email == null || email.isBlank())
                ? "" : email.trim().toLowerCase(Locale.ROOT);
        String householdId = HouseholdId.of(lastName, postcode);
        return normalizedTelephone + "|" + normalizedEmail + "|" + householdId;
    }
}

